CREATE TABLE "Tenant"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL);CREATE TABLE "Workflow"("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"publishedVersion" INTEGER);CREATE INDEX "Workflow_tenantId_idx" ON "Workflow"("tenantId");CREATE TABLE "WorkflowVersion"("id" TEXT PRIMARY KEY,"workflowId" TEXT NOT NULL REFERENCES "Workflow"("id") ON DELETE CASCADE,"version" INTEGER NOT NULL,"definition" JSONB NOT NULL,"publishedAt" TIMESTAMP(3),UNIQUE("workflowId","version"));CREATE TABLE "Execution"("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE,"workflowId" TEXT NOT NULL,"status" TEXT NOT NULL,"stepId" TEXT NOT NULL,"attempt" INTEGER NOT NULL DEFAULT 0,"leaseUntil" TIMESTAMP(3),"idempotencyKey" TEXT NOT NULL,UNIQUE("tenantId","idempotencyKey"));CREATE INDEX "Execution_tenantId_status_leaseUntil_idx" ON "Execution"("tenantId","status","leaseUntil");CREATE TABLE "Credential"("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"encryptedValue" TEXT NOT NULL,UNIQUE("tenantId","name"));
